  "sim.dairy-farm.title": "Allevamento di latticini",
  "sim.dairy-farm.desc": "Gestisci un piccolo allevamento di latticini: programmi di alimentazione, cicli di mungitura e salute del bestiame per massimizzare la resa.",
  "sim.poultry-farm.title": "Allevamento avicolo",
  "sim.poultry-farm.desc": "Gestisci un allevamento avicolo commerciale: alimentazione, salute e obiettivi di produzione per i gruppi di polli da carne e ovaiole.",
  "sim.cattle-dairy.title": "Bovini & latticini",
  "sim.cattle-dairy.desc": "Gestisci un ranch di bovini e un’unità di latticini, bilanciando gestione dei pascoli, riproduzione e produzione di latte.",
  "sim.sheep-farm.title": "Allevamento di pecore",
  "sim.sheep-farm.desc": "Gestisci un allevamento di pecore attraverso cicli stagionali: parto dei agnelli, tosatura e vendite al mercato.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Agisci come ingegnere di un Centro Operazioni di Rete — diagnostica e risolvi incidenti infrastrutturali in tempo reale sotto pressione.",
  "sim.mobile-repair.title": "Officina di riparazione mobile",
  "sim.mobile-repair.desc": "Diagnostica e ripara smartphone — sostituzioni schermo, problemi alla batteria e guasti della scheda madre.",
  "sim.laptop-repair.title": "Officina di riparazione laptop",
  "sim.laptop-repair.desc": "Risolvi e ripara i laptop: guasti hardware, problemi BIOS e sostituzioni dei componenti.",
  "sim.perfume-lab.title": "Laboratorio di profumi",
  "sim.perfume-lab.desc": "Mescola oli essenziali e composti aromatici per creare fragranze distintive e raggiungere standard di qualità.",
  "sim.detergent-lab.title": "Laboratorio detergenti",
  "sim.detergent-lab.desc": "Formula prodotti per la pulizia — bilancia tensioattivi, riempitivi e test di prestazione entro il budget.",
  "sim.skin-care-lab.title": "Laboratorio per la cura della pelle",
  "sim.skin-care-lab.desc": "Sviluppa e testa formulazioni cosmetiche, rispettando standard di sicurezza e obiettivi di efficacia.",
  "sim.woodworking.title": "Laboratorio di falegnameria",
  "sim.woodworking.desc": "Gestisci un laboratorio di falegnameria su misura: pianifica le commesse, gestisci i materiali e consegna i mobili in tempo e nei limiti del budget.",
  "sim.aluminum-glazing.title": "Alluminio & vetrature",
  "sim.aluminum-glazing.desc": "Gestisci un’attività di lavorazione dell’alluminio e installazione vetri, dalla quotazione al completamento in cantiere.",
  "sim.global-kitchen.title": "Cucina globale",
  "sim.global-kitchen.desc": "Guida una cucina di ristorante: gestisci menu, staff, costi e soddisfazione dei clienti tra i turni di servizio.",
  "sim.chocolate-factory.title": "Fabbrica di cioccolato",
  "sim.chocolate-factory.desc": "Gestisci una fabbrica di prodotti di pasticceria — approvvigionamento di cacao, pianificazione della produzione e controllo qualità.",
  "sim.solar-energy.title": "Impianto di energia solare",
  "sim.solar-energy.desc": "Progetta e gestisci un impianto solare — dimensiona i pannelli, gestisci l’esportazione in rete e monitora il ROI.",
  "sim.hvac-systems.title": "Impianti HVAC",
  "sim.hvac-systems.desc": "Installa e mantieni sistemi di riscaldamento, ventilazione e aria condizionata per edifici commerciali.",
  "sim.logistics-supply.title": "Logistica & supply chain",
  "sim.logistics-supply.desc": "Ottimizza le operazioni del magazzino, la pianificazione dei veicoli e i rapporti con i fornitori per raggiungere i KPI di consegna.",
  "sim.barber-salon.title": "Salone da barbiere",
  "sim.barber-salon.desc": "Gestisci un salone da barbiere: appuntamenti, turni del personale, prezzi e strategie di fidelizzazione dei clienti.",
  "sim.board-surgeon.title": "Chirurgo del reparto",
  "sim.board-surgeon.desc": "Prendi decisioni chirurgiche ad alto rischio in un teatro operatorio simulato — gestione del tempo e sicurezza del paziente.",
  "sim.english-journey.title": "Percorso di inglese",
  "sim.english-journey.desc": "Guida gli studenti attraverso un programma strutturato di inglese, adattandolo a livelli di abilità diversi.",
  "sim.music-training.title": "Studio di formazione musicale",
  "sim.music-training.desc": "Gestisci una scuola di musica: pianifica le lezioni, gestisci gli strumenti e monitora i progressi degli studenti verso i saggi.",
  "sim.trade-tycoon.title": "Trade Tycoon",
  "sim.trade-tycoon.desc": "Costruisci un impero commerciale: compra a basso prezzo, vendi ad alto prezzo, gestisci inventario e flusso di cassa su più mercati.",
  "sim.vehicle-diagnostics.title": "Simulatore di diagnostica e riparazione del veicolo",
  "sim.vehicle-diagnostics.desc": "Diagnostica codici guasto OBD-II, individua guasti elettrici e gestisci un flusso di riparazione auto nel mondo reale.",
  "sim.marine-vessel.title": "Tracciamento di navi marittime & logistica marittima",
