  "jungle.howTo.1": "Sei bloccato nella giungla — fai scelte per sopravvivere",
  "jungle.howTo.2": "Ogni scelta influisce su HP e punteggio in modo diverso",
  "jungle.howTo.3": "Se i tuoi HP arrivano a 0, il gioco finisce",
  "jungle.howTo.4": "Sopravvivi a tutti gli 8 scenari per vincere!",
  "jungle.scene6": "Trovi un uccello ferito. Cosa fai?",
  "jungle.s6c1": "Trasportalo con attenzione — potrebbe condurti a un sentiero (+5 HP, +25 pt)",
  "jungle.s6c2": "Lascialo — prenderti cura di lui spreca energia (0 HP, +10 pt)",
  "jungle.scene7": "Un fiume blocca il tuo cammino. L’acqua sembra veloce.",
  "jungle.s7c1": "Costruisci una zattera con tronchi caduti (−5 HP, +40 pt)",
  "jungle.s7c2": "Vai a monte per trovare un punto poco profondo (+10 HP, +20 pt)",
  "jungle.scene8": "Vedi del fumo in lontananza.",
  "jungle.s8c1": "Vai verso il fumo — potrebbe essere un soccorso! (+15 HP, +45 pt)",
  "jungle.s8c2": "Eviterei — potrebbe esserci un incendio (−5 HP, +15 pt)",
  "jungle.scene9": "Cala la notte. Ti serve riparo.",
  "jungle.s9c1": "Sali su un albero alto per proteggerti dai predatori (+10 HP, +30 pt)",
  "jungle.s9c2": "Costruisci un riparo a terra con rami (−5 HP, +35 pt)",
  "jungle.scene10": "Trovi un frutto che non riconosci. Hai una fame terribile.",
  "jungle.s10c1": "Mangi Il frutto — sei allo stremo! (−20 HP, +30 pt)",
  "jungle.s10c2": "Prova prima un micropezzo sulla pelle (0 HP, +20 pt)",
  "jungle.scene11": "Una grande serpe si avvolge sul percorso.",
  "jungle.s11c1": "Allontanati lentamente e trova un percorso alternativo (+5 HP, +30 pt)",
  "jungle.s11c2": "Cerca di spaventarla (−25 HP, +40 pt)",
  "jungle.scene12": "Senti una cascata — le tue scorte d’acqua sono critiche.",
  "jungle.s12c1": "Segui il suono per trovare acqua fresca (+20 HP, +35 pt)",
  "jungle.s12c2": "Ignoralo e continua ad andare avanti (−15 HP, +20 pt)",
  "jungle.scene13": "Una tempesta si sta avvicinando rapidamente.",
  "jungle.s13c1": "Trova terreno alto e riparati (+10 HP, +25 pt)",
  "jungle.s13c2": "Continua a muoverti per scappare (−10 HP, +30 pt)",
  "jungle.scene14": "Trovi una grotta. Sta facendo buio.",
  "jungle.s14c1": "Entra nella grotta per ripararti (+15 HP, +30 pt)",
  "jungle.s14c2": "Dormi sotto un albero — la grotta potrebbe essere occupata (+5 HP, +20 pt)",
  "jungle.scene15": "Sei esausto. Una radura davanti sembra sicura.",
  "jungle.s15c1": "Riposa e recupera (+20 HP, +20 pt)",
  "jungle.s15c2": "Vai avanti — riposare qui è pericoloso (−5 HP, +30 pt)",
  "jungle.scene16": "Trovi una mappa vecchia incisa su un albero.",
  "jungle.s16c1": "Segui la direzione della mappa (+5 HP, +40 pt)",
  "jungle.s16c2": "Ignorala — potrebbe essere superata (0 HP, +10 pt)",
  "jungle.scene17": "Cinghiali selvatici attraversano il tuo cammino in modo aggressivo.",
  "jungle.s17c1": "Arrampicati subito sull’albero più vicino (+5 HP, +30 pt)",
  "jungle.s17c2": "Stai fermo e urla (−20 HP, +35 pt)",
  "jungle.scene18": "Trovi un campo abbandonato con provviste.",
  "jungle.s18c1": "Prendi tutto ciò che è utile (+20 HP, +50 pt)",
  "jungle.s18c2": "Lascia stare — potrebbe servirti dopo (0 HP, +10 pts)",
  "jungle.scene19": "Un leone? No: una scimmia ruba la tua borsa del cibo!",
  "jungle.s19c1": "Insegui la scimmia (−10 HP, +40 pts)",
  "jungle.s19c2": "Lascia perdere — non vale l’energia (+0 HP, +15 pts)",
  "jungle.scene20": "Senti passare un elicottero sopra di te.",
  "jungle.s20c1": "Accendi subito un fuoco di segnalazione! (+30 HP, +60 pts)",
  "jungle.s20c2": "Agita le braccia — potrebbe vederti (+5 HP, +40 pts)",
