  "earmaster.howTo.1": "Ascolta attentamente la nota musicale riprodotta",
  "earmaster.howTo.2": "Scegli quale nota hai sentito tra le 7 opzioni",
  "earmaster.howTo.3": "Usa il pulsante Play per ripetere la nota una volta",
  "earmaster.howTo.4": "Completa 10 round per vedere il tuo punteggio finale",
  "uno.howTo.1": "Abbina la carta in cima al mazzo per colore o numero",
  "uno.howTo.2": "Tocca una carta nella tua mano per giocarla",
  "uno.howTo.3": "Se non hai corrispondenze, tocca Estrai per aggiungere una carta",
  "uno.howTo.4": "Vince chi svuota prima la mano!",
  "briscola.howTo.1": "Briscola è un gioco di carte italiano di prese",
  "briscola.howTo.2": "Il seme di briscola (Briscola) batte tutti gli altri semi",
  "briscola.howTo.3": "Vinci prese per guadagnare punti — Asso=11, 3=10, Re=4, Donna=3, Fante=2",
  "briscola.howTo.4": "Vince chi ottiene il punteggio più alto dopo che sono state giocate tutte le carte",
  "card99.howTo.1": "Gioca carte per mantenere il totale in corso a 99 o meno",
  "card99.howTo.2": "Carte speciali: Re=0, Donna=valore fisso, Fante=−10, Asso=1 o 11",
  "card99.howTo.3": "Spingi il totale oltre 99 e perdi una vita",
  "card99.howTo.4": "Vince chi resta in piedi per ultimo con le vite!",
  "dominoes.howTo.1": "Abbina i numeri alle estremità della catena di domino",
  "dominoes.howTo.2": "Gioca tessere dalla tua mano che corrispondono a un’estremità aperta",
  "dominoes.howTo.3": "Pesca dal mazzo se non puoi giocare",
  "dominoes.howTo.4": "Vince chi svuota prima la mano (o con il minor totale di punti)!",
  "farkle.howTo.1": "Lancia 6 dadi e metti da parte quelli che fanno punteggio",
  "farkle.howTo.2": "1=100 pts · 5=50 pts · Tris = valore della faccia × 100",
  "farkle.howTo.3": "Se NON escono dadi in punteggio al lancio, è un FARKLE — perdi il turno!",
  "farkle.howTo.4": "Accantona i punti per tenerli, oppure rilancia per più rischio/ricompensa",
  "quiz.howTo.1": "Rispondi a 20 domande a scelta multipla il più velocemente possibile",
  "quiz.howTo.2": "Ogni domanda ha 3 secondi — rispondi in fretta!",
  "quiz.howTo.3": "Risposte corrette più veloci ottengono più punti bonus",
  "quiz.howTo.4": "Completa tutte le domande per vedere la tua classifica finale",
  "memory.howTo.1": "Capovolgi due carte alla volta per trovare le coppie corrispondenti",
  "memory.howTo.2": "Se corrispondono, restano a faccia in su",
  "memory.howTo.3": "Se no, entrambe tornano a faccia in giù — ricorda dove erano!",
  "memory.howTo.4": "Abbina tutte le coppie con il minor numero di mosse possibile per fare punti alti",
  "word.howTo.1": "Ricomponi le lettere mescolate per formare la parola nascosta",
  "word.howTo.2": "Tocca le lettere nell’ordine corretto per costruire la tua risposta",
  "word.howTo.3": "Usa il pulsante Suggerimento se sei bloccato (costa punti)",
  "word.howTo.4": "Completa 8 parole per finire il puzzle",
  "hangman.howTo.1": "Indovina la parola nascosta una lettera alla volta",
  "hangman.howTo.2": "Lettera corretta = rivela la lettera nella parola",
  "hangman.howTo.3": "Lettera sbagliata = perdi una delle 6 possibilità",
  "hangman.howTo.4": "Rivela l’intera parola prima di 6 tentativi errati per vincere",
