  "legal.privacy.collect.messaging.heading": "Messaggi su Facebook Messenger e Instagram Direct",
  "legal.privacy.collect.messaging.text": "Quando scrivi a una pagina o a un account Visionex su Facebook Messenger o Instagram Direct, Meta ci trasmette il testo che hai scritto, il proprio identificativo circoscritto che ti riguarda (un ID legato alla pagina o all'account Instagram, non il tuo profilo, la tua e-mail o il tuo numero di telefono), l'identificativo del messaggio e l'ora di invio. Conserviamo questi dati per leggere la tua domanda, mantenere l'ordine della conversazione, evitare di rispondere due volte allo stesso messaggio e affidarla a una persona quando l'assistenza automatica non basta. Il testo del tuo messaggio viene elaborato da fornitori terzi di intelligenza artificiale per generare una risposta. Non riceviamo mai la tua password di Facebook o Instagram, il tuo elenco di amici o follower, né i dati del tuo profilo.",
  "legal.privacy.third.meta.name": "Meta Platforms (Facebook Messenger, Instagram Direct, WhatsApp)",
  "legal.privacy.third.meta.purpose": "Recapita i messaggi che invii a Visionex tramite Messenger, Instagram Direct o WhatsApp e ci consente di farti pervenire le nostre risposte. Meta tratta tali messaggi sulle proprie piattaforme secondo i propri termini e la propria informativa sulla privacy.",
  "legal.privacy.deletionLink": "Per chiedere la cancellazione dei dati ricevuti da Facebook Messenger o Instagram Direct, segui le istruzioni su",
  "legal.dataDeletion.title": "Richiesta di cancellazione dei dati",
  "legal.dataDeletion.intro": "Questa pagina spiega come chiedere la cancellazione dei dati che Visionex conserva su di te, compresi quelli ricevuti da Meta quando ci hai scritto su Facebook Messenger o Instagram Direct.",
  "legal.dataDeletion.howTitle": "Come richiedere la cancellazione",
  "legal.dataDeletion.step1": "Scrivici un'e-mail con oggetto «Richiesta di cancellazione dei dati».",
  "legal.dataDeletion.step2": "Indica a quale servizio si riferiscono i dati — per esempio un messaggio inviato alla pagina Visionex su Facebook Messenger o Instagram Direct — e all'incirca quando ci hai contattati, così da poter individuare la conversazione corretta. Se hai un account Visionex, invia la richiesta dall'indirizzo e-mail associato a quell'account.",
  "legal.dataDeletion.step3": "Confermiamo di aver ricevuto la richiesta, cancelliamo quanto conservato e ti rispondiamo indicando che cosa è stato rimosso.",
  "legal.dataDeletion.contact": "Invia le richieste a",
  "legal.dataDeletion.whatTitle": "Che cosa viene cancellato",
  "legal.dataDeletion.whatBody": "Per Facebook Messenger e Instagram Direct cancelliamo la registrazione della conversazione che conserviamo: il testo che hai inviato, le risposte che ti abbiamo inviato, l'identificativo circoscritto che Meta ci ha fornito sul tuo conto, gli identificativi dei messaggi e le marche temporali. Per un account Visionex cancelliamo o rendiamo anonimi i dati personali a esso collegati. Non possiamo cancellare nulla di quanto Meta conserva sulle proprie piattaforme: la copia della conversazione nella tua casella di Messenger o Instagram appartiene al tuo account Meta e puoi eliminarla tu stesso da lì.",
  "legal.dataDeletion.timingTitle": "Quanto tempo richiede",
  "legal.dataDeletion.timingBody": "Cerchiamo di completare la cancellazione entro 30 giorni dalla conferma della tua richiesta. Quando siamo tenuti a conservare una registrazione limitata — per sicurezza, prevenzione delle frodi, risoluzione delle controversie o un obbligo di legge — manteniamo solo quanto necessario e cancelliamo il resto.",
  "legal.dataDeletion.accountTitle": "Cancellare un account Visionex",
  "legal.dataDeletion.accountBody": "Se hai un account Visionex puoi anche chiederci di chiuderlo del tutto, usando lo stesso indirizzo. La chiusura comporta la cancellazione o l'anonimizzazione dei dati personali collegati all'account, fatta salva la conservazione limitata descritta sopra.",
  "legal.dataDeletion.footer": "Per il dettaglio completo di ciò che raccogliamo e perché, consulta l'",
